26: func run() error {
27: 	if len(os.Args) < 2 {
28: 		return fmt.Errorf("usage: go run ./sketch/sketch7 [--model <model.yaml>] [--agent <agent.yaml>] [--workflow <workflow.yaml>] [--session-id <id> | --state <path>] [--stop-token <token>] --prompt <text>")
29: 	}
30: 	args, err := parseArgs(os.Args[1:])
31: 	if err != nil {
32: 		return err
33: 	}
34: 	memory := catalog.NewMemory()
35: 	for _, path := range []string{args.modelPath, args.agentPath, args.workflowPath} {
36: 		if strings.TrimSpace(path) == "" {
37: 			continue
38: 		}
39: 		raw, err := os.ReadFile(path)
40: 		if err != nil {
41: 			return err
42: 		}
43: 		if err := catalog.LoadIntoMemory(memory, raw); err != nil {
44: 			return err
45: 		}
46: 	}
47: 	modelDef, ok := firstModel(memory)
48: 	if !ok {
49: 		modelDef = defaultModelDefinition()
50: 	}
51: 	agentDef, ok := firstAgent(memory)
52: 	if !ok {
53: 		agentDef = defaultAgentDefinition(modelDef.Name)
54: 	}
55: 	workflowDef, hasWorkflow := firstWorkflow(memory)
56: 	toolRegistry := buildToolRegistry()
57: 	hydratedAgent, err := compile.HydrateAgent(agentDef, modelDef, toolRegistry)
58: 	if err != nil {
59: 		return err
60: 	}
61: 	projections, maxHistory, err := prompt.BuildProjectionPlan(agentDef)
62: 	if err != nil {
63: 		return err
64: 	}
65: 	providerAdapter, err := providerFromEnv()
66: 	if err != nil {
67: 		return err
68: 	}
69: 	statePath := strings.TrimSpace(args.statePath)
70: 	if statePath == "" && strings.TrimSpace(args.sessionID) != "" {
71: 		statePath = filepath.Join(".maelstrom", "sessions", args.sessionID+".json")
72: 	}
73: 	var sessionHistory *logs.SessionHistory
74: 	var workflowHistory *logs.WorkflowHistory
75: 	if statePath != "" {
76: 		if _, err := os.Stat(statePath); err == nil {
77: 			loadedSession, loadedWorkflow, err := logs.LoadState(statePath)
78: 			if err != nil {
79: 				return err
80: 			}
81: 			sessionHistory = loadedSession
82: 			workflowHistory = loadedWorkflow
83: 		}
84: 	}
85: 	if sessionHistory == nil {
86: 		sessionID := strings.TrimSpace(args.sessionID)
87: 		if sessionID == "" {
88: 			sessionID = "session-001"
89: 		}
90: 		sessionHistory = logs.NewSessionHistory(sessionID)
91: 	}
92: 	if hasWorkflow && workflowHistory == nil {
93: 		workflowID := sessionHistory.SessionID + ":" + workflowDef.Name
94: 		workflowHistory = logs.NewWorkflowHistory(workflowID)
95: 	}
96: 	if hasWorkflow && !hasBindingRecord(sessionHistory) {
97: 		bindingID := "bind-" + sessionHistory.SessionID
98: 		sessionHistory.Append(logs.SessionWorkflowBindingRecord{SessionBaseRecord: sessionHistory.NextRecord("workflow_binding_ref"), BindingID: bindingID, WorkflowID: workflowHistory.WorkflowID, Action: "bind"})
99: 		workflowHistory.Append(logs.WorkflowBindingRefRecord{WorkflowBaseRecord: workflowHistory.NextRecord("workflow_binding_ref"), BindingID: bindingID, AgentID: agentDef.Name, Action: "bind"})
100: 	}
101: 	if strings.TrimSpace(args.prompt) != "" {
102: 		sessionHistory.Append(logs.UserMessageRecord{SessionBaseRecord: sessionHistory.NextRecord("user"), Content: args.prompt})
103: 	}
104: 	loop := runner.Loop{
105: 		Provider:    providerAdapter,
106: 		Tools:       toolRegistry,
107: 		Projections: projections,
108: 		MaxHistory:  maxHistory,
109: 		StopToken:   args.stopToken,
110: 	}
111: 	var workflowDefPtr *defs.WorkflowDefinition
112: 	if hasWorkflow {
113: 		workflowDefPtr = &workflowDef
114: 	}
115: 	runErr := loop.Run(hydratedAgent, agentDef, workflowDefPtr, sessionHistory, workflowHistory)
116: 	if statePath != "" {
117: 		if err := logs.SaveState(statePath, sessionHistory, workflowHistory); err != nil {
118: 			if runErr != nil {
119: 				return fmt.Errorf("%v (also failed to save state: %w)", runErr, err)
120: 			}
121: 			return err
122: 		}
123: 	}
124: 	if runErr != nil {
125: 		return runErr
126: 	}
127: 	for _, record := range sessionHistory.Records {
128: 		fmt.Println(describeRecord(record))
129: 	}
130: 	return nil
131: }
