146: 		switch args[i] {
147: 		case "--model":
148: 			i++
149: 			if i >= len(args) {
150: 				return cliArgs{}, fmt.Errorf("missing value for --model")
151: 			}
152: 			parsed.modelPath = args[i]
153: 		case "--agent":
154: 			i++
155: 			if i >= len(args) {
156: 				return cliArgs{}, fmt.Errorf("missing value for --agent")
157: 			}
158: 			parsed.agentPath = args[i]
159: 		case "--workflow":
160: 			i++
161: 			if i >= len(args) {
162: 				return cliArgs{}, fmt.Errorf("missing value for --workflow")
163: 			}
164: 			parsed.workflowPath = args[i]
165: 		case "--prompt":
166: 			i++
167: 			if i >= len(args) {
168: 				return cliArgs{}, fmt.Errorf("missing value for --prompt")
169: 			}
170: 			parsed.prompt = args[i]
171: 		case "--session-id":
172: 			i++
173: 			if i >= len(args) {
174: 				return cliArgs{}, fmt.Errorf("missing value for --session-id")
175: 			}
176: 			parsed.sessionID = args[i]
177: 		case "--state":
178: 			i++
179: 			if i >= len(args) {
180: 				return cliArgs{}, fmt.Errorf("missing value for --state")
181: 			}
182: 			parsed.statePath = args[i]
183: 		case "--stop-token":
184: 			i++
185: 			if i >= len(args) {
186: 				return cliArgs{}, fmt.Errorf("missing value for --stop-token")
187: 			}
188: 			parsed.stopToken = args[i]
189: 		default:
190: 			return cliArgs{}, fmt.Errorf("unknown argument %q", args[i])
191: 		}
192: 	}
193: 	if parsed.prompt == "" && parsed.statePath == "" && parsed.sessionID == "" {
194: 		return cliArgs{}, fmt.Errorf("--prompt is required unless resuming with --state or --session-id")
195: 	}
196: 	return parsed, nil
197: }
