99: func trimMessages(messages []Message, maxMessages int) []Message {
100: 	if len(messages) <= maxMessages || maxMessages <= 0 {
101: 		return append([]Message(nil), messages...)
102: 	}
103: 	blocks := blockMessages(messages)
104: 	selected := make([]messageBlock, 0, len(blocks))
105: 	count := 0
106: 	for i := len(blocks) - 1; i >= 0; i-- {
107: 		block := blocks[i]
108: 		if count+len(block.Messages) > maxMessages && len(selected) > 0 {
109: 			continue
110: 		}
111: 		selected = append(selected, block)
112: 		count += len(block.Messages)
113: 		if count >= maxMessages {
114: 			break
115: 		}
116: 	}
117: 	anchor := latestUserAnchor(blocks)
118: 	if anchor != nil && !containsAnchor(selected, *anchor) {
119: 		selected = append(selected, *anchor)
120: 	}
121: 	if len(selected) > 0 {
122: 		selected = expandLeadingToolExchange(selected, blocks)
123: 	}
124: 	reverseBlocks(selected)
125: 	trimmed := make([]Message, 0, maxMessages+2)
126: 	for _, block := range selected {
127: 		trimmed = append(trimmed, block.Messages...)
128: 	}
129: 	return trimmed
130: }
