184: func reverseBlocks(blocks []messageBlock) {
185: 	for i, j := 0, len(blocks)-1; i < j; i, j = i+1, j-1 {
186: 		blocks[i], blocks[j] = blocks[j], blocks[i]
187: 	}
188: }
